// WF02.A step 1 — expand the files[] array from WF01 into N items.
// WF01 ships one aggregated item per execution: { files: [{session_id, file:{...}, ...}, ...] }.
// Downstream nodes process each file in turn.
const inp = $input.first() && $input.first().json;
if (!inp) return [];
const files = (inp.files || []);
return files.map(f => ({ json: f }));

// WF02.A PDF normalize — emit uniform per-file result.
const meta = $('Expand Files').item.json;
const j = $json;
const text = (typeof j.text === 'string' ? j.text : '');
const hasErr = j.error || (!text);
return {
  json: {
    file_id: meta.file && meta.file.file_id,
    file_unique_id: meta.file && meta.file.file_unique_id,
    file_name: meta.file && meta.file.file_name,
    mime_type: meta.file && meta.file.mime_type,
    session_id: meta.session_id,
    source: 'pdf',
    text: text,
    error: hasErr ? (j.error && j.error.message || j.error || 'pdf_extract_empty') : null
  }
};

// WF02.A DOCX normalize — emit uniform per-file result.
const meta = $('Expand Files').item.json;
const j = $json;
let text = '';
let err = null;
if (j && typeof j.text === 'string') {
  text = j.text;
} else if (j && j.error) {
  err = String(j.error);
} else {
  err = 'docx_extract_unknown_response';
}
return {
  json: {
    file_id: meta.file && meta.file.file_id,
    file_unique_id: meta.file && meta.file.file_unique_id,
    file_name: meta.file && meta.file.file_name,
    mime_type: meta.file && meta.file.mime_type,
    session_id: meta.session_id,
    source: 'docx',
    text: text,
    error: err
  }
};

// WF02.A image normalize — emit uniform per-file result with base64.
const meta = $('Expand Files').item.json;
const j = $json;
let image_b64 = (j && typeof j.image_base64 === 'string' && j.image_base64.length > 0) ? j.image_base64 : null;
return {
  json: {
    file_id: meta.file && meta.file.file_id,
    file_unique_id: meta.file && meta.file.file_unique_id,
    file_name: meta.file && meta.file.file_name,
    mime_type: meta.file && meta.file.mime_type,
    session_id: meta.session_id,
    source: 'image',
    image_b64: image_b64,
    error: image_b64 ? null : 'no_binary_data'
  }
};

// WF02.A unsupported MIME — record error, do not crash session.
const meta = $('Expand Files').item.json;
return {
  json: {
    file_id: meta.file && meta.file.file_id,
    file_unique_id: meta.file && meta.file.file_unique_id,
    file_name: meta.file && meta.file.file_name,
    mime_type: meta.file && meta.file.mime_type,
    session_id: meta.session_id,
    source: 'unsupported',
    error: 'unsupported_mime'
  }
};

// WF02 — collect normalized file results from the Merge All Branches input stream.
// All items from PDF / DOCX / Image / Unsupported branches arrive here as a single stream.
const items = $input.all().map(i => i.json).filter(f => f && f.file_id);
return [{ json: { results: items } }];

// WF02.B step 1 — assemble the Claude classification request.
const agg = $('Aggregate Results').first().json;
const results = agg.results || [];

const templateRows = $('Read Template').all().map(i => i.json);
const templateList = templateRows.length === 0
  ? '(no templates configured — operator should seed the template tab)'
  : templateRows.map(r => {
      const req = r.is_required === true || String(r.is_required).toUpperCase() === 'TRUE' ? ' (REQUIRED)' : '';
      const aliases = r.synonyms ? ` aliases [${r.synonyms}]` : '';
      const fields = r.required_fields ? ` fields ${r.required_fields}` : '';
      return `- ${r.document_type}${req}:${aliases}${fields}`;
    }).join('\n');

const systemText = `You are a document classifier for Ukrainian accounting and HR pipelines.

You receive 1–6 documents per session, each is one of these types from the
TEMPLATE list. Classify each, extract these fields if present:
  - date (ISO YYYY-MM-DD)
  - number (document number)
  - amount (numeric, base currency UAH; null if not applicable)
  - contractor (counterparty name)

For each file, also output a confidence 0.0–1.0 — how sure you are about
the type assignment.

If you cannot identify the type from the TEMPLATE list, return type
"unknown" with confidence reflecting how close it came to a known type.

Return STRICT JSON with this schema. No prose, no markdown fence:
{
  "files": [
    {
      "file_id": "...",
      "detected_type": "...",
      "date": "YYYY-MM-DD" | null,
      "number": "..." | null,
      "amount": 12345.67 | null,
      "contractor": "..." | null,
      "confidence": 0.0–1.0
    }
  ]
}

TEMPLATE list (canonical types and synonyms):
${templateList}

Language: documents may be Ukrainian, Russian, or English. Field names in
output stay in English. Field VALUES stay in original language.`;

const content = [];
for (const r of results) {
  content.push({ type: 'text', text: `--- FILE ${r.file_id} ---` });
  if (r.text && r.text.length > 0) {
    content.push({ type: 'text', text: r.text });
  } else if (r.image_b64) {
    content.push({
      type: 'image',
      source: { type: 'base64', media_type: r.mime_type || 'image/jpeg', data: r.image_b64 }
    });
  } else if (r.error) {
    content.push({ type: 'text', text: `[file unavailable: ${r.error}]` });
  } else {
    content.push({ type: 'text', text: '[file empty]' });
  }
}

return [{
  json: {
    body: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 2048,
      system: [{ type: 'text', text: systemText, cache_control: { type: 'ephemeral' } }],
      messages: [{ role: 'user', content }]
    },
    results,
    systemText
  }
}];

// WF02.B — parse Haiku JSON, attach model_used, decide if Sonnet retry needed.
const httpResp = $input.first().json;
const buildOutput = $('Build Haiku Request').first().json;
const inputResults = buildOutput.results || [];

let parsed = null;
let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

const haikuByFileId = {};
if (parsed && Array.isArray(parsed.files)) {
  for (const f of parsed.files) haikuByFileId[f.file_id] = f;
}

const merged = inputResults.map(r => {
  if (r.error) {
    return { ...r, detected_type: null, confidence: 0, model_used: null, needs_retry: false };
  }
  const cls = haikuByFileId[r.file_id] || {};
  const conf = typeof cls.confidence === 'number' ? cls.confidence : 0;
  return {
    ...r,
    detected_type: cls.detected_type || (parseError ? null : 'unknown'),
    date: cls.date || null,
    number: cls.number || null,
    amount: typeof cls.amount === 'number' ? cls.amount : null,
    contractor: cls.contractor || null,
    confidence: conf,
    model_used: 'haiku-4.5',
    needs_retry: !!parseError || conf < 0.7
  };
});

const needs_retry_any = merged.some(r => r.needs_retry && !r.error);

return [{
  json: {
    results: merged,
    needs_retry: needs_retry_any,
    usage_haiku: httpResp.usage || {},
    parse_error_haiku: parseError,
    systemText: buildOutput.systemText
  }
}];

// WF02.B retry — build Sonnet 4.6 request with only the files needing retry.
const inp = $input.first().json;
const results = inp.results;
const retryFiles = results.filter(r => r.needs_retry && !r.error);
const systemText = inp.systemText;

const content = [];
for (const r of retryFiles) {
  content.push({ type: 'text', text: `--- FILE ${r.file_id} ---` });
  if (r.text && r.text.length > 0) {
    content.push({ type: 'text', text: r.text });
  } else if (r.image_b64) {
    content.push({
      type: 'image',
      source: { type: 'base64', media_type: r.mime_type || 'image/jpeg', data: r.image_b64 }
    });
  }
}

return [{
  json: {
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 2048,
      system: [{ type: 'text', text: systemText, cache_control: { type: 'ephemeral' } }],
      messages: [{ role: 'user', content }]
    },
    results,
    retryFileIds: retryFiles.map(r => r.file_id),
    usage_haiku: inp.usage_haiku,
    parse_error_haiku: inp.parse_error_haiku
  }
}];

// WF02.B — merge Sonnet retry results back into the Haiku results array.
const httpResp = $input.first().json;
const buildOutput = $('Build Sonnet Request').first().json;
const allResults = buildOutput.results || [];

let parsed = null;
let parseError = null;
try {
  const text = (httpResp.content && httpResp.content[0] && httpResp.content[0].text) || '';
  const cleaned = text.replace(/^```(?:json)?\n?|\n?```$/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

const sonnetByFileId = {};
if (parsed && Array.isArray(parsed.files)) {
  for (const f of parsed.files) sonnetByFileId[f.file_id] = f;
}

const merged = allResults.map(r => {
  if (r.needs_retry && !r.error && sonnetByFileId[r.file_id]) {
    const cls = sonnetByFileId[r.file_id];
    const conf = typeof cls.confidence === 'number' ? cls.confidence : 0;
    return {
      ...r,
      detected_type: cls.detected_type || r.detected_type,
      date: cls.date || r.date,
      number: cls.number || r.number,
      amount: typeof cls.amount === 'number' ? cls.amount : r.amount,
      contractor: cls.contractor || r.contractor,
      confidence: conf,
      model_used: 'sonnet-4.6',
      needs_retry: false
    };
  }
  return r;
});

return [{
  json: {
    results: merged,
    usage_haiku: buildOutput.usage_haiku || {},
    usage_sonnet: httpResp.usage || {},
    parse_error_haiku: buildOutput.parse_error_haiku || null,
    parse_error_sonnet: parseError
  }
}];
